cat > /private/tmp/claude-501/-Users-guillaumeloulier-PhpstormProjects-oss-elephc--claude-worktrees-streams-csv-signature/c8dbe38f-1f79-484f-9b83-62bacab9ca56/scratchpad/fix_srsubj_diag.py <<'PYEOF'
import os

os.chdir('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature')
p = 'src/builtins/string/str_replace.rs'
s = open(p).read()

old = '''fn check(cx: &mut BuiltinCheckCtx) -> Result<PhpType, CompileError> {
    let subject = cx.checker.infer_type(&cx.args[2], cx.env)?;
    if matches!(subject, PhpType::Array(_) | PhpType::AssocArray { .. }) {
        return Ok(PhpType::Array(Box::new(PhpType::Str)));
    }
    Ok(PhpType::Str)
}'''
new = '''fn check(cx: &mut BuiltinCheckCtx) -> Result<PhpType, CompileError> {
    let subject = cx.checker.infer_type(&cx.args[2], cx.env)?;
    if matches!(subject, PhpType::AssocArray { .. }) {
        // php keeps the subject's keys, so a keyed subject answers a keyed array. Saying so here
        // rather than letting the string coercion refuse it downstream is the difference between a
        // diagnostic that names the limit and one that leaks a backend type.
        return Err(CompileError::new(
            cx.span,
            "str_replace() subject array with string or sparse keys is not supported yet; \\
             a list subject works",
        ));
    }
    if matches!(subject, PhpType::Array(_)) {
        return Ok(PhpType::Array(Box::new(PhpType::Str)));
    }
    Ok(PhpType::Str)
}'''
assert s.count(old) == 1
s = s.replace(old, new)
open(p, 'w').write(s)
print('hash-subject diagnostic added')
PYEOF
python3 /private/tmp/claude-501/-Users-guillaumeloulier-PhpstormProjects-oss-elephc--claude-worktrees-streams-csv-signature/c8dbe38f-1f79-484f-9b83-62bacab9ca56/scratchpad/fix_srsubj_diag.py && cargo build 2>&1 | grep -iE "^error|^warning:|-->" | head -6; echo BUILT: hash-subject diagnostic added BUILT
